    syncNavigationUrl(){
        if(this.state.sessionStatus!=='ready'||!this.state.user||!this.state.organization_id)return;
        try {
            const current=window.location.search;
            const query=ipdamsNavigationQuery(this.state,current);
            const desired=query?'?'+query:'';
            if(desired!==current)
                window.history.replaceState(window.history.state,'',window.location.pathname+desired+window.location.hash);
        }catch(_){/* Navigation works even if browser history rewriting is blocked. */}
    }
    goDashboardFromBrand(event){
        // A real link gives a reliable dashboard destination if JavaScript fails.
        // Keep ordinary clicks in-app; preserve browser modified-click behavior.
        if (!event || event.defaultPrevented || event.button !== 0 ||
            event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
        event.preventDefault();
        this.goDashboard();
    }
    goDashboard(){
        // Same action as the Dashboard sidebar item, for sidebar and top-bar
        // branding. URL navigation state is cleared by syncNavigationUrl().
        this.eligibleRequest=(this.eligibleRequest||0)+1;
        this.setState({tab:'Dashboard',error:'',success:'',details:null,viewType:'',bir2307Dialog:null,
            atc_dialog:'',atc_action:'',atc_selected_code:'',
            prCreateOpen:false,prQuickAdd:null,dvComposeOpen:false,
            tbCatalogOpen:false,tbCoFormOpen:false,tbCoDetail:null,tbCatalogView:null,tbProfilesConfirmDiscardId:0,tbTransferModal:'',tbTransferDetail:null,
            eligibleLoading:false,eligibleError:'',eligibleLoadedFor:''});
    }
    disableViewerEditingControls(){
        // Presentation-only. Server authorization denies mutations independently.
        const root=document.getElementById('root');if(!root)return;
        const deny=/^(?:save|submit|add |new |create|prepare |approve|finalize|issue |release |post |cancel |delete|remove |update |edit |correct |register |upload |transfer |reverse |return |record |activate |deactivate |reset |confirm |generate |close |apply |proceed to|proceed with|start new)/i;
        root.querySelectorAll('button').forEach(button=>{
            if(button.classList.contains('navitem'))return;
            if(/^change my password$/i.test((button.textContent||'').trim()))return;
            if(button.type==='submit'||deny.test((button.textContent||'').trim())){
                button.disabled=true;button.setAttribute('aria-disabled','true');
                button.title='Read-only Division MOOE reviewer';
            }
        });
        root.querySelectorAll('input[type="file"]').forEach(el=>{el.disabled=true;});
    }
