            if(!this.canOperateWorkspace() || String(this.state.organization_id)!==q.org){
                this.setState({prQuickAddError:'Workspace changed. Reopen the catalog dialog in the correct office.'});return;
            }
            const code=String(q.unitQuickCode||'').trim().toUpperCase();
            const name=String(q.unitQuickName||'').trim();
            if(!/^[A-Z0-9_-]{1,30}$/.test(code)||!name||name.length>80){
                this.setState({prQuickAddError:'Enter a unit code (up to 30 letters/numbers) and a descriptive name (up to 80 characters).'});return;
            }
